<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');require_once dirname(__DIR__).'/private/operations.php';require_once dirname(__DIR__).'/private/ui.php';
$id=max(0,(int)($_GET['id']??0));$day=(string)($_GET['date']??date('Y-m-d'));if(!zgsValidDate($day))$day=date('Y-m-d');$all=isset($_GET['cancelled']);
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{if(($_POST['action']??'')==='save')$id=opsSaveAppointment($pdo,(int)$_SESSION['admin_id'],$_POST,$id);elseif(($_POST['action']??'')==='cancel')opsCancelAppointment($pdo,(int)$_SESSION['admin_id'],$id,opsVersion($_POST));else throw new RuntimeException('Aktion unbekannt.');$_SESSION['app_notice']='Terminänderung gespeichert. Bestehende Planvorschläge müssen neu berechnet werden.';}catch(Throwable $e){gszUiError($e);}redirect('appointments.php?date='.$day.($id?'&id='.$id:''));}
$items=[];$a=[];$history=[];$conflicts=[];try{opsRequire($pdo);$q=$pdo->prepare('SELECT * FROM planning_appointments WHERE day BETWEEN ? AND ?'.($all?'':' AND cancelled_at IS NULL').' ORDER BY day,start_time,id LIMIT 201');$q->execute([$day,planDate($day,30)]);$items=$q->fetchAll();if($id){$q=$pdo->prepare('SELECT * FROM planning_appointments WHERE id=?');$q->execute([$id]);$a=$q->fetch()?:throw new RuntimeException('Termin fehlt.');$history=opsHistory($pdo,'appointment',$id);if(!$a['cancelled_at']){$q=$pdo->prepare('SELECT id,title,start_time,end_time FROM planning_appointments WHERE id<>? AND day=? AND cancelled_at IS NULL AND start_time<? AND end_time>? ORDER BY start_time LIMIT 20');$q->execute([$id,$a['day'],$a['end_time'],$a['start_time']]);$conflicts=$q->fetchAll();}}}catch(Throwable $e){gszUiError($e);}gszPageStart('Termine und Erinnerungen');
?><p>Fixtermine blockieren die Planung. Erinnerungen erscheinen lokal im Dashboard; keine automatische E-Mail oder Pushnachricht. Terminänderungen verschieben keine Aufgaben ungefragt.</p><p><a href="appointments.php?new=1&amp;date=<?=e($day)?>">Fixtermin hinzufügen</a> · <a href="planner.php?date=<?=e($day)?>">Tagesplanung</a></p><form method="get"><label>Ab Datum<input type="date" name="date" value="<?=e($day)?>" required></label><label><input type="checkbox" name="cancelled" <?=$all?'checked':''?>> Stornierte anzeigen</label><button>31 Tage anzeigen</button></form>
<?php if($a||isset($_GET['new'])):?><section class="card"><h2><?=$a?'Termin bearbeiten':'Neuer Fixtermin'?></h2><?php foreach($conflicts as $c):?><p class="error">Überlappung mit <?=e($c['title'].' · '.$c['start_time'].'–'.$c['end_time'])?>. Keine automatische Verschiebung.</p><?php endforeach?><?php if(empty($a['cancelled_at'])):?><form method="post"><?php gszFields('save');?><input type="hidden" name="row_version" value="<?=(int)($a['row_version']??0)?>"><label>Datum<input name="appointment_day" type="date" required value="<?=e($a['day']??$day)?>"></label><label>Beginn<input name="appointment_start" type="time" required value="<?=e(substr($a['start_time']??'',0,5))?>"></label><label>Ende<input name="appointment_end" type="time" required value="<?=e(substr($a['end_time']??'',0,5))?>"></label><label>Beschreibung<input name="appointment_title" maxlength="190" required value="<?=e($a['title']??'')?>"></label><label>Adresse (optional)<input name="address" maxlength="255" value="<?=e($a['address']??'')?>"></label><label>Erinnerung vorher (Minuten, lokal)<input type="number" min="0" max="1440" name="reminder_minutes" value="<?=(int)($a['reminder_minutes']??30)?>"></label><label>Notiz (optional)<textarea name="appointment_notes" maxlength="5000"><?=e($a['notes']??'')?></textarea></label><button>Termin speichern</button></form><?php if($id):?><form method="post"><?php gszFields('cancel');?><input type="hidden" name="row_version" value="<?=(int)$a['row_version']?>"><button>Termin stornieren (Historie erhalten)</button></form><?php endif?><?php else:?><p>Termin storniert, bleibt historisch erhalten.</p><?php endif?></section><?php endif?>
<section class="card"><h2>Termine im Zeitraum (maximal 200)</h2><?php foreach(array_slice($items,0,200) as $item):?><p><a href="?id=<?=(int)$item['id']?>&amp;date=<?=e($day)?>"><?=e($item['day'].' · '.substr($item['start_time'],0,5).'–'.substr($item['end_time'],0,5).' · '.$item['title'])?></a> <?=empty($item['cancelled_at'])?'':'· Storniert'?></p><?php endforeach?><?php if(count($items)>200):?><p class="error">Weitere Termine vorhanden. Zeitraum über Startdatum eingrenzen.</p><?php endif?></section><?php if($history):?><section class="card"><h2>Historie</h2><?php foreach($history as $h):?><details><summary><?=e($h['created_at'].' UTC · '.$h['action'])?></summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?=e($h['changes_json'])?></pre></details><?php endforeach?></section><?php endif?><?php gszPageEnd();?>
